SET NOCOUNT ON;
-- Needed by the filtered unique indexes; sqlcmd leaves it off by default.
SET QUOTED_IDENTIFIER ON;

-- order_db: the members' shop (order-service). Written by hand; not produced by generate_seed.py.
-- Catalogue and orders only. The money stays in Oracle: an order carries the ledger's hold_id and
-- the account ids as plain numbers, with no foreign key across the two systems.
-- The three products are the ones the mobile app ships as its sample catalogue, with the same ids.


IF OBJECT_ID(N'coop_shop_product', N'U') IS NULL
CREATE TABLE coop_shop_product (
    product_id BIGINT IDENTITY(100,1) PRIMARY KEY,
    sku VARCHAR(64) NOT NULL UNIQUE,
    name VARCHAR(150) NOT NULL,
    category VARCHAR(50) NOT NULL,
    unit VARCHAR(80) NOT NULL,
    price NUMERIC(18, 4) NOT NULL,
    original_price NUMERIC(18, 4),
    badge VARCHAR(50),
    farm_source VARCHAR(255),
    stock_quantity INT NOT NULL DEFAULT 999,
    is_active INT NOT NULL DEFAULT 1,
    created_at DATETIME2(6) NOT NULL DEFAULT SYSUTCDATETIME()
);

IF OBJECT_ID(N'coop_shop_order', N'U') IS NULL
CREATE TABLE coop_shop_order (
    order_id BIGINT IDENTITY(1000,1) PRIMARY KEY,
    reference_no VARCHAR(64) NOT NULL UNIQUE,
    customer_id BIGINT NOT NULL,
    source_account_id BIGINT NOT NULL,
    destination_account_id BIGINT,
    hold_id BIGINT,
    stage VARCHAR(30) NOT NULL DEFAULT 'HELD',
    total_amount NUMERIC(18, 4) NOT NULL,
    pickup_branch VARCHAR(150) NOT NULL DEFAULT 'PureSilver Central Mall Depot',
    pickup_pass_token VARCHAR(128) NOT NULL,
    pickup_time_slot VARCHAR(100) NOT NULL DEFAULT '4:00 PM - 6:00 PM',
    created_at DATETIME2(6) NOT NULL DEFAULT SYSUTCDATETIME(),
    updated_at DATETIME2(6) NOT NULL DEFAULT SYSUTCDATETIME()
);
IF NOT EXISTS (SELECT 1 FROM sys.indexes WHERE name = N'idx_coop_order_customer' AND object_id = OBJECT_ID(N'coop_shop_order'))
    CREATE INDEX idx_coop_order_customer ON coop_shop_order(customer_id);
IF NOT EXISTS (SELECT 1 FROM sys.indexes WHERE name = N'idx_coop_order_stage' AND object_id = OBJECT_ID(N'coop_shop_order'))
    CREATE INDEX idx_coop_order_stage ON coop_shop_order(stage);

IF OBJECT_ID(N'coop_shop_order_item', N'U') IS NULL
CREATE TABLE coop_shop_order_item (
    item_id BIGINT IDENTITY(1000,1) PRIMARY KEY,
    order_id BIGINT NOT NULL REFERENCES coop_shop_order(order_id) ON DELETE CASCADE,
    product_id BIGINT,
    product_name VARCHAR(150) NOT NULL,
    quantity INT NOT NULL,
    unit_price NUMERIC(18, 4) NOT NULL,
    subtotal NUMERIC(18, 4) NOT NULL
);
IF NOT EXISTS (SELECT 1 FROM sys.indexes WHERE name = N'idx_coop_item_order' AND object_id = OBJECT_ID(N'coop_shop_order_item'))
    CREATE INDEX idx_coop_item_order ON coop_shop_order_item(order_id);

